model.jaffle_shop.metricflow_time_spine.raw_code:
{{
    config(
        materialized = 'table',
    )
}}

with days as (

    {{
        dbt.date_spine(
            'day',
            "cast('2000-01-01' as date)",
            "cast('2030-01-01' as date)"
        )
    }}

),

final as (
    select cast(date_day as date) as date_day
    from days
)

select * from final

